// ---- local raw-C-string helpers (no libc dependency in this crate) ----

/// Faithful `strlen` over a raw NUL-terminated byte pointer.
unsafe fn c_strlen(s: *const u8) -> usize {
    let mut n = 0usize;
    unsafe {
        while *s.add(n) != 0 {
            n += 1;
        }
    }
    n
}

/// Faithful `strstr` over raw NUL-terminated byte pointers.
unsafe fn c_strstr(haystack: *const u8, needle: *const u8) -> Option<*const u8> {
    unsafe {
        let needle_len = c_strlen(needle);
        if needle_len == 0 {
            return Some(haystack);
        }
        let mut h = haystack;
        while *h != 0 {
            let mut k = 0usize;
            while k < needle_len && *h.add(k) == *needle.add(k) && *h.add(k) != 0 {
                k += 1;
            }
            if k == needle_len {
                return Some(h);
            }
            h = h.add(1);
        }
        None
    }
}

/// Faithful `atoi` over a NUL-terminated byte buffer (decimal, optional
/// leading sign, stops at first non-digit — matches libc `atoi` behavior).
fn c_atoi(buf: &[u8]) -> c_int {
    let mut i = 0usize;
    while i < buf.len() && (buf[i] == b' ' || buf[i] == 9) {
        i += 1;
    }
    let mut neg = false;
    if i < buf.len() && (buf[i] == b'-' || buf[i] == b'+') {
        neg = buf[i] == b'-';
        i += 1;
    }
    let mut val: c_int = 0;
    while i < buf.len() && buf[i].is_ascii_digit() {
        val = val.wrapping_mul(10).wrapping_add((buf[i] - b'0') as c_int);
        i += 1;
    }
    if neg { -val } else { val }
}
